// Trecho (em forma de fita, já pronto para <path fill=.../>) de uma veia
// profunda com status único (sem trecho de refluxo parcial, ao contrário de
// magna/parva) — mesmo helper usado por FEMORAL_RIBBON/TIBIAIS_RIBBON.
export function fitaVeiaSimples(spine, half, yA, yB) {
  return pathFromTriples(sliceSpine(spine, half, yA, yB));
}

export const CORES = {
  "pérvia e competente": "#1f6fb2",
  "pérvia e incompetente": "#c0392b",
  "não compressível e sem fluxo (trombose)": "#2b2f33",
  "ausente": "#aab4bc",
  "recanalização parcial": "#d99a3d",
};

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

export function catmullRom(points, closed) {
  const p = closed
    ? [points[points.length - 1]].concat(points, [points[0], points[1]])
    : [points[0]].concat(points, [points[points.length - 1]]);
  let d = `M ${points[0][0].toFixed(2)},${points[0][1].toFixed(2)} `;
  const n = points.length - (closed ? 0 : 1);
  for (let i = 0; i < n; i++) {
    const p0 = p[i], p1 = p[i + 1], p2 = p[i + 2], p3 = p[i + 3];
    const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
    const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
    d += `C ${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${p2[0].toFixed(2)},${p2[1].toFixed(2)} `;
  }
  if (closed) d += "Z";
  return d;
}

export function ribbonPath(spine, half) {
  const left = spine.map((p, i) => [p[0] - half[i], p[1]]);
  const right = spine.map((p, i) => [p[0] + half[i], p[1]]);
  return catmullRom(left.concat(right.slice().reverse()), true);
}

export function interpAt(spine, half, y) {
  for (let i = 0; i < spine.length - 1; i++) {
    const a = spine[i], b = spine[i + 1];
    if (y >= a[1] && y <= b[1]) {
      const t = (y - a[1]) / (b[1] - a[1]);
      return [a[0] + (b[0] - a[0]) * t, y, half[i] + (half[i + 1] - half[i]) * t];
    }
  }
  if (y <= spine[0][1]) return [spine[0][0], spine[0][1], half[0]];
  const last = spine.length - 1;
  return [spine[last][0], spine[last][1], half[last]];
}

export function sliceSpine(spine, half, yA, yB) {
  const pts = [];
  const a = interpAt(spine, half, yA);
  pts.push([a[0], yA, a[2]]);
  for (let i = 0; i < spine.length; i++) {
    const y = spine[i][1];
    if (y > yA + 0.01 && y < yB - 0.01) pts.push([spine[i][0], y, half[i]]);
  }
  const b = interpAt(spine, half, yB);
  pts.push([b[0], yB, b[2]]);
  return pts;
}

export function pathFromTriples(triples) {
  return ribbonPath(triples.map((p) => [p[0], p[1]]), triples.map((p) => p[2]));
}

export function yFromField(field, val, landmark) {
  const v = parseFloat(val) || 0;
  if (field === landmark.topField) return landmark.top;
  if (field === "joelho") return landmark.joelho;
  if (field === "tornozelo") return landmark.tornozelo;
  if (field === "cm_acima_joelho") return clamp(landmark.joelho - v * PX_PER_CM, landmark.top, landmark.tornozelo);
  if (field === "cm_abaixo_joelho") return clamp(landmark.joelho + v * PX_PER_CM, landmark.top, landmark.tornozelo);
  if (field === "cm_acima_tornozelo") return clamp(landmark.tornozelo - v * PX_PER_CM, landmark.top, landmark.tornozelo);
  return null;
}

const LEGENDA_SEGMENTO = {
  JSF: "JSF",
  JSP: "JSP",
  joelho: "joelho",
  cm_acima_joelho: "cm acima do joelho",
  cm_abaixo_joelho: "cm abaixo do joelho",
  cm_acima_tornozelo: "cm acima do tornozelo",
  tornozelo: "tornozelo",
};

export function fmt(field, val) {
  if (!field) return field;
  if (field.indexOf("cm_") === 0 && val) return `${val} ${LEGENDA_SEGMENTO[field]}`;
  return LEGENDA_SEGMENTO[field] || field;
}

// Espelha exatamente a arvore de decisao de gerarConclusaoPorLado() em MMIIVenoso.js
export function classify(veinLabel, topField, ini, fim, iniVal, fimVal) {
  if (!ini || !fim) return `Insuficiência da safena ${veinLabel}`;
  const iniFmt = fmt(ini, iniVal), fimFmt = fmt(fim, fimVal);
  if (iniFmt.includes(topField) && fimFmt.includes("tornozelo")) return `Insuficiência total da safena ${veinLabel}`;
  if ((iniFmt.includes("joelho") || iniFmt.includes(topField)) && fimFmt.includes("tornozelo")) return `Insuficiência parcial da safena ${veinLabel}`;
  if (iniFmt.includes("joelho") && fimFmt.includes("joelho")) return `Insuficiência segmentar da safena ${veinLabel}`;
  if (iniFmt.includes(topField) && fimFmt.includes("joelho")) return `Insuficiência parcial da safena ${veinLabel}`;
  return `Insuficiência da safena ${veinLabel}`;
}

// Retorna os trechos coloridos (path + cor) da veia, a partir dos MESMOS
// campos que o formulario ja usa (status, inicio, fim, inicio_valor, fim_valor).
export function construirSegmentosVeia({ spine, half, landmark, status, ini, fim, iniVal, fimVal }) {
  if (status === "ausente") {
    const pts = sliceSpine(spine, half, landmark.top, landmark.tornozelo).map((p) => [p[0], p[1]]);
    return {
      segments: [{ d: catmullRom(pts, false), color: CORES.ausente, tracejado: true }],
      dotColor: "#ffffff",
      dotStroke: CORES.ausente,
    };
  }
  if (status !== "pérvia e incompetente") {
    const cor = CORES[status] || CORES.ausente;
    return {
      segments: [{ d: pathFromTriples(sliceSpine(spine, half, landmark.top, landmark.tornozelo)), color: cor }],
      dotColor: cor,
    };
  }
  const needIni = ini && ini.indexOf("cm_") === 0;
  const needFim = fim && fim.indexOf("cm_") === 0;
  const completo = ini && fim && (!needIni || iniVal) && (!needFim || fimVal);
  if (!completo) {
    return {
      segments: [{ d: pathFromTriples(sliceSpine(spine, half, landmark.top, landmark.tornozelo)), color: CORES["pérvia e incompetente"] }],
      dotColor: CORES["pérvia e incompetente"],
    };
  }
  let yStart = yFromField(ini, iniVal, landmark);
  let yEnd = yFromField(fim, fimVal, landmark);
  if (yStart > yEnd) { const t = yStart; yStart = yEnd; yEnd = t; }
  const segments = [];
  if (yStart > landmark.top + 2) {
    segments.push({ d: pathFromTriples(sliceSpine(spine, half, landmark.top, yStart)), color: CORES["pérvia e competente"] });
  }
  segments.push({ d: pathFromTriples(sliceSpine(spine, half, yStart, yEnd)), color: CORES["pérvia e incompetente"] });
  if (yEnd < landmark.tornozelo - 2) {
    segments.push({ d: pathFromTriples(sliceSpine(spine, half, yEnd, landmark.tornozelo)), color: CORES["pérvia e competente"] });
  }
  const dotColor = yStart <= landmark.top + 2 ? CORES["pérvia e incompetente"] : CORES["pérvia e competente"];
  const refluxo = {
    yStart,
    yEnd,
    iniLabel: fmt(ini, iniVal),
    fimLabel: fmt(fim, fimVal),
    marcarIni: yStart > landmark.top + 2,
    marcarFim: yEnd < landmark.tornozelo - 2,
  };
  return { segments, dotColor, refluxo };
}

export function gerarConclusaoVisual(veinLabel, topField, status, ini, fim, iniVal, fimVal) {
  if (status === "ausente") return `Ausência de safena ${veinLabel} identificável ao exame`;
  if (status === "não compressível e sem fluxo (trombose)") return `Tromboflebite da safena ${veinLabel}`;
  if (status === "pérvia e incompetente") return classify(veinLabel, topField, ini, fim, iniVal, fimVal);
  return null;
}

const PERF_SEGMENTO_FIELD = {
  "cm acima do joelho": "cm_acima_joelho",
  "cm abaixo do joelho": "cm_abaixo_joelho",
  "cm acima do tornozelo": "cm_acima_tornozelo",
};

// Posiciona o marcador da veia perfurante na vista medial, usando a mesma
// escala anatomica da Safena Magna (o campo "segmento" do formulario ja usa
// os mesmos textos: "cm acima do joelho" etc).
export function posicaoPerfurante(segmentoLabel, valor) {
  const field = PERF_SEGMENTO_FIELD[segmentoLabel];
  if (!field) return null;
  const y = yFromField(field, valor || 0, LANDMARK_MAGNA);
  const [x] = interpAt(VSM_SPINE, VSM_HALF, y);
  return { x: x - 22, y };
}

// ---- Sistema venoso profundo (Femorais, Poplítea, Tibiais, Gastrocnêmicas, Soleares) ----
// Usa as mesmas opções do formulário (profOptions em MMIIVenoso.js):
// "pérvia e competente" | "pérvia e incompetente" |
// "não compressível e sem fluxo (sugestivo de trombose)" |
// "semi compressível, sugestivo de recanalização parcial"
export function corStatusProfundo(status) {
  if (!status) return CORES["pérvia e competente"];
  if (status.indexOf("não compressível") === 0) return CORES["não compressível e sem fluxo (trombose)"];
  if (status.indexOf("semi compressível") === 0) return CORES["recanalização parcial"];
  if (status === "pérvia e incompetente") return CORES["pérvia e incompetente"];
  return CORES["pérvia e competente"];
}

// Prioridade (mais grave primeiro) para quando um único traçado do desenho
// representa mais de uma veia profunda (ex.: Femoral Comum + Superficial).
const PRIORIDADE_PROFUNDO = [
  "não compressível",
  "pérvia e incompetente",
  "semi compressível",
];
export function piorCorProfundo(statusList) {
  const lista = (statusList || []).filter(Boolean);
  for (const chave of PRIORIDADE_PROFUNDO) {
    const achado = lista.find((s) => s.indexOf(chave) === 0 || s === chave);
    if (achado) return corStatusProfundo(achado);
  }
  return CORES["pérvia e competente"];
}

// Mesma lógica de gerarConclusaoPorLado() em MMIIVenoso.js para o sistema profundo
export function conclusoesSistemaProfundo(profundas) {
  const valores = Object.values(profundas || {});
  const conclusoes = [];
  if (valores.some((v) => v && v.includes("não compressível"))) {
    conclusoes.push("Trombose venosa profunda");
  }
  if (valores.some((v) => v && v.includes("semi compressível"))) {
    conclusoes.push("Sinais de recanalização parcial do sistema venoso profundo");
  }
  if (valores.some((v) => v && v.includes("incompetente"))) {
    conclusoes.push("Insuficiência de sistema venoso profundo");
  }
  return conclusoes;
}
